#!/bin/bash\n\n# Kaspa Full-Stack Infrastructure - Official Deployment Script\n# klassik.99pace.space - Industrial Grade Blockchain Explorer\n# Version: 2.0 (Official kaspa-ng Implementation)\n\nset -e  # Exit on any error\n\n# Color codes for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Configuration\nPROJECT_NAME=\"klassik-kaspa-official\"\nDOMAIN=\"klassik.99pace.space\"\nEMAIL=\"admin@99pace.space\"\n\n# Function to print colored output\nprint_status() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nprint_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nprint_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nprint_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\n# Function to check if command exists\ncommand_exists() {\n    command -v \"$1\" >/dev/null 2>&1\n}\n\n# Function to check system requirements\ncheck_system() {\n    print_status \"Checking system requirements...\"\n    \n    # Check OS\n    if [[ \"$OSTYPE\" != \"linux-gnu\"* ]]; then\n        print_error \"This script requires Linux. Detected: $OSTYPE\"\n        exit 1\n    fi\n    \n    # Check if running as root or with sudo\n    if [[ $EUID -ne 0 ]]; then\n        print_error \"This script must be run as root or with sudo\"\n        exit 1\n    fi\n    \n    # Check available memory (minimum 8GB recommended)\n    MEMORY_GB=$(free -g | awk '/^Mem:/{print $2}')\n    if [[ $MEMORY_GB -lt 8 ]]; then\n        print_warning \"Warning: System has only ${MEMORY_GB}GB RAM. Recommended: 8GB+\"\n    fi\n    \n    # Check available disk space (minimum 100GB recommended)\n    DISK_GB=$(df -BG / | awk 'NR==2 {print $4}' | sed 's/G//')\n    if [[ $DISK_GB -lt 100 ]]; then\n        print_warning \"Warning: System has only ${DISK_GB}GB free space. Recommended: 100GB+\"\n    fi\n    \n    print_success \"System requirements check completed\"\n}\n\n# Function to install dependencies\ninstall_dependencies() {\n    print_status \"Installing system dependencies...\"\n    \n    # Update package manager\n    apt-get update -qq\n    \n    # Install required packages\n    apt-get install -y \\\n        curl \\\n        wget \\\n        git \\\n        unzip \\\n        htop \\\n        nginx \\\n        certbot \\\n        python3-certbot-nginx \\\n        ufw \\\n        fail2ban \\\n        logrotate\n    \n    # Install Docker if not present\n    if ! command_exists docker; then\n        print_status \"Installing Docker...\"\n        curl -fsSL https://get.docker.com -o get-docker.sh\n        sh get-docker.sh\n        systemctl enable docker\n        systemctl start docker\n        rm get-docker.sh\n    fi\n    \n    # Install Docker Compose if not present\n    if ! command_exists docker-compose; then\n        print_status \"Installing Docker Compose...\"\n        curl -L \"https://github.com/docker/compose/releases/download/v2.23.0/docker-compose-$(uname -s)-$(uname -m)\" -o /usr/local/bin/docker-compose\n        chmod +x /usr/local/bin/docker-compose\n    fi\n    \n    print_success \"Dependencies installed successfully\"\n}\n\n# Function to setup firewall\nsetup_firewall() {\n    print_status \"Configuring firewall...\"\n    \n    # Reset UFW to default\n    ufw --force reset\n    \n    # Set default policies\n    ufw default deny incoming\n    ufw default allow outgoing\n    \n    # Allow essential services\n    ufw allow 22/tcp   # SSH\n    ufw allow 80/tcp   # HTTP\n    ufw allow 443/tcp  # HTTPS\n    \n    # Allow Kaspa node communication\n    ufw allow 16110/tcp # Kaspad RPC\n    ufw allow 16111/tcp # Kaspad P2P\n    \n    # Enable firewall\n    ufw --force enable\n    \n    print_success \"Firewall configured successfully\"\n}\n\n# Function to create project directory structure\nsetup_directories() {\n    print_status \"Setting up project directories...\"\n    \n    # Create project directory\n    PROJECT_DIR=\"/opt/klassik-official\"\n    mkdir -p $PROJECT_DIR\n    cd $PROJECT_DIR\n    \n    # Create required directories\n    mkdir -p {\n        logs,\n        ssl,\n        data/postgres,\n        data/prometheus,\n        data/grafana,\n        data/indexer,\n        backups,\n        monitoring,\n        scripts\n    }\n    \n    # Set proper permissions\n    chown -R 1000:1000 data/\n    chmod -R 755 data/\n    \n    export PROJECT_DIR\n    print_success \"Project directories created: $PROJECT_DIR\"\n}\n\n# Function to clone official repositories\nclone_repositories() {\n    print_status \"Cloning official Kaspa repositories...\"\n    \n    cd $PROJECT_DIR\n    \n    # Clone kaspa-rest-server\n    if [[ ! -d \"kaspa-rest-server\" ]]; then\n        git clone https://github.com/kaspa-ng/kaspa-rest-server.git\n        print_success \"Cloned kaspa-rest-server repository\"\n    fi\n    \n    # Clone kaspa-explorer\n    if [[ ! -d \"kaspa-explorer\" ]]; then\n        git clone https://github.com/kaspa-ng/kaspa-explorer.git\n        print_success \"Cloned kaspa-explorer repository\"\n    fi\n    \n    # Clone simply-kaspa-indexer\n    if [[ ! -d \"simply-kaspa-indexer\" ]]; then\n        git clone https://github.com/supertypo/simply-kaspa-indexer.git\n        print_success \"Cloned simply-kaspa-indexer repository\"\n    fi\n}\n\n# Function to setup SSL certificates\nsetup_ssl() {\n    print_status \"Setting up SSL certificates...\"\n    \n    # Stop nginx temporarily\n    systemctl stop nginx 2>/dev/null || true\n    \n    # Check if certificates already exist\n    if [[ -f \"/etc/letsencrypt/live/$DOMAIN/fullchain.pem\" ]]; then\n        print_warning \"SSL certificates already exist for $DOMAIN\"\n        return 0\n    fi\n    \n    # Get SSL certificate\n    certbot certonly \\\n        --standalone \\\n        --non-interactive \\\n        --agree-tos \\\n        --email $EMAIL \\\n        --domains $DOMAIN,www.$DOMAIN\n    \n    if [[ $? -eq 0 ]]; then\n        print_success \"SSL certificates obtained successfully\"\n        \n        # Setup automatic renewal\n        echo \"0 12 * * * /usr/bin/certbot renew --quiet\" | crontab -\n        print_success \"SSL auto-renewal configured\"\n    else\n        print_warning \"SSL certificate setup failed. Will use self-signed certificates.\"\n        \n        # Create self-signed certificates as fallback\n        mkdir -p /etc/letsencrypt/live/$DOMAIN\n        openssl req -x509 -nodes -days 365 -newkey rsa:2048 \\\n            -keyout \"/etc/letsencrypt/live/$DOMAIN/privkey.pem\" \\\n            -out \"/etc/letsencrypt/live/$DOMAIN/fullchain.pem\" \\\n            -subj \"/C=US/ST=State/L=City/O=Organization/CN=$DOMAIN\"\n        \n        print_warning \"Self-signed certificates created\"\n    fi\n}\n\n# Function to create docker-compose configuration\nsetup_docker_config() {\n    print_status \"Creating Docker Compose configuration...\"\n    \n    cd $PROJECT_DIR\n    \n    # Copy our pre-configured docker-compose file\n    cp /opt/klassik/docker-compose.official.yml ./docker-compose.yml\n    cp /opt/klassik/.env.production ./.env\n    \n    # Update configuration with actual paths\n    sed -i \"s|\\./frontend|$PROJECT_DIR/kaspa-explorer|g\" docker-compose.yml\n    sed -i \"s|\\./monitoring|$PROJECT_DIR/monitoring|g\" docker-compose.yml\n    sed -i \"s|\\./nginx|$PROJECT_DIR/nginx|g\" docker-compose.yml\n    \n    # Create nginx configuration directory\n    mkdir -p nginx\n    cp /opt/klassik/nginx/klassik-official.conf nginx/klassik.conf\n    \n    print_success \"Docker configuration created\"\n}\n\n# Function to start services\nstart_services() {\n    print_status \"Starting Kaspa services...\"\n    \n    cd $PROJECT_DIR\n    \n    # Pull latest images\n    docker-compose pull\n    \n    # Start services in correct order\n    print_status \"Starting database...\"\n    docker-compose up -d postgres\n    \n    # Wait for database to be ready\n    print_status \"Waiting for database to be ready...\"\n    sleep 30\n    \n    print_status \"Starting indexer...\"\n    docker-compose up -d indexer\n    \n    # Wait for indexer to start populating data\n    print_status \"Waiting for indexer to initialize...\"\n    sleep 60\n    \n    print_status \"Starting REST API server...\"\n    docker-compose up -d kaspa-rest-server\n    \n    # Wait for API server to be ready\n    print_status \"Waiting for API server to be ready...\"\n    sleep 30\n    \n    print_status \"Starting frontend...\"\n    docker-compose up -d kaspa-explorer\n    \n    print_status \"Starting monitoring services...\"\n    docker-compose up -d prometheus grafana\n    \n    print_status \"Starting reverse proxy...\"\n    docker-compose up -d nginx\n    \n    print_success \"All services started successfully\"\n}\n\n# Function to setup monitoring\nsetup_monitoring() {\n    print_status \"Setting up monitoring configuration...\"\n    \n    cd $PROJECT_DIR\n    \n    # Copy monitoring configurations from our setup\n    cp -r /opt/klassik/monitoring ./\n    \n    # Update Prometheus targets\n    cat > monitoring/prometheus.yml << EOF\nglobal:\n  scrape_interval: 15s\n  evaluation_interval: 15s\n\nscrape_configs:\n  - job_name: 'kaspa-rest-server'\n    static_configs:\n      - targets: ['172.20.0.20:8000']\n    metrics_path: '/metrics'\n    scrape_interval: 30s\n\n  - job_name: 'postgres'\n    static_configs:\n      - targets: ['172.20.0.10:5432']\n    scrape_interval: 30s\n\n  - job_name: 'nginx'\n    static_configs:\n      - targets: ['172.20.0.40:80']\n    scrape_interval: 30s\n\n  - job_name: 'node-exporter'\n    static_configs:\n      - targets: ['host.docker.internal:9100']\n    scrape_interval: 30s\nEOF\n\n    print_success \"Monitoring configuration completed\"\n}\n\n# Function to verify deployment\nverify_deployment() {\n    print_status \"Verifying deployment...\"\n    \n    cd $PROJECT_DIR\n    \n    # Check if all containers are running\n    RUNNING_CONTAINERS=$(docker-compose ps --services --filter \"status=running\" | wc -l)\n    TOTAL_CONTAINERS=$(docker-compose ps --services | wc -l)\n    \n    if [[ $RUNNING_CONTAINERS -eq $TOTAL_CONTAINERS ]]; then\n        print_success \"All containers are running ($RUNNING_CONTAINERS/$TOTAL_CONTAINERS)\"\n    else\n        print_warning \"Some containers are not running ($RUNNING_CONTAINERS/$TOTAL_CONTAINERS)\"\n    fi\n    \n    # Test API endpoints\n    sleep 30  # Give services time to start\n    \n    print_status \"Testing API endpoints...\"\n    \n    # Test health endpoint\n    if curl -f http://localhost:8080/ping >/dev/null 2>&1; then\n        print_success \"✅ REST API server is responding\"\n    else\n        print_warning \"❌ REST API server is not responding\"\n    fi\n    \n    # Test frontend\n    if curl -f http://localhost:3000 >/dev/null 2>&1; then\n        print_success \"✅ Frontend is responding\"\n    else\n        print_warning \"❌ Frontend is not responding\"\n    fi\n    \n    # Test monitoring\n    if curl -f http://localhost:9090 >/dev/null 2>&1; then\n        print_success \"✅ Prometheus is responding\"\n    else\n        print_warning \"❌ Prometheus is not responding\"\n    fi\n    \n    if curl -f http://localhost:3001 >/dev/null 2>&1; then\n        print_success \"✅ Grafana is responding\"\n    else\n        print_warning \"❌ Grafana is not responding\"\n    fi\n}\n\n# Function to create management scripts\nsetup_management_scripts() {\n    print_status \"Creating management scripts...\"\n    \n    cd $PROJECT_DIR\n    \n    # Create status script\n    cat > scripts/status.sh << 'EOF'\n#!/bin/bash\ncd /opt/klassik-official\necho \"=== Kaspa Infrastructure Status ===\"\ndocker-compose ps\necho \"\"\necho \"=== Service Health Checks ===\"\ncurl -s http://localhost:8080/ping | jq .\ncurl -s http://localhost:8080/info/health | jq .\nEOF\n    \n    # Create restart script\n    cat > scripts/restart.sh << 'EOF'\n#!/bin/bash\ncd /opt/klassik-official\necho \"Restarting Kaspa services...\"\ndocker-compose restart\necho \"Services restarted.\"\nEOF\n    \n    # Create backup script\n    cat > scripts/backup.sh << 'EOF'\n#!/bin/bash\nBACKUP_DIR=\"/opt/klassik-official/backups\"\nDATE=$(date +\"%Y%m%d_%H%M%S\")\n\necho \"Creating backup: $DATE\"\n\n# Backup database\ndocker-compose exec -T postgres pg_dump -U kaspa kaspa > \"$BACKUP_DIR/kaspa_db_$DATE.sql\"\n\n# Backup configurations\ntar -czf \"$BACKUP_DIR/config_$DATE.tar.gz\" docker-compose.yml .env nginx/ monitoring/\n\necho \"Backup completed: $BACKUP_DIR\"\nEOF\n    \n    # Create update script\n    cat > scripts/update.sh << 'EOF'\n#!/bin/bash\ncd /opt/klassik-official\necho \"Updating Kaspa services...\"\ndocker-compose pull\ndocker-compose up -d\necho \"Update completed.\"\nEOF\n    \n    # Make scripts executable\n    chmod +x scripts/*.sh\n    \n    print_success \"Management scripts created in $PROJECT_DIR/scripts/\"\n}\n\n# Function to display completion information\nshow_completion_info() {\n    print_success \"\\n🎉 Kaspa Full-Stack Infrastructure Deployment Completed!\"\n    \n    echo -e \"\\n${BLUE}=== Deployment Summary ===${NC}\"\n    echo -e \"Domain: ${GREEN}https://$DOMAIN${NC}\"\n    echo -e \"Project Directory: ${GREEN}$PROJECT_DIR${NC}\"\n    echo \"\"\n    echo -e \"${BLUE}=== Service URLs ===${NC}\"\n    echo -e \"Frontend: ${GREEN}https://$DOMAIN${NC}\"\n    echo -e \"API: ${GREEN}https://$DOMAIN/api/${NC}\"\n    echo -e \"Health: ${GREEN}https://$DOMAIN/health${NC}\"\n    echo -e \"Monitoring: ${GREEN}https://$DOMAIN/monitoring/${NC}\"\n    echo -e \"Metrics: ${GREEN}https://$DOMAIN/metrics/${NC}\"\n    echo \"\"\n    echo -e \"${BLUE}=== Local Development URLs ===${NC}\"\n    echo -e \"Frontend: ${GREEN}http://localhost:3000${NC}\"\n    echo -e \"API: ${GREEN}http://localhost:8080${NC}\"\n    echo -e \"Prometheus: ${GREEN}http://localhost:9090${NC}\"\n    echo -e \"Grafana: ${GREEN}http://localhost:3001${NC} (admin:klassik_admin_2026!)\"\n    echo \"\"\n    echo -e \"${BLUE}=== Management Commands ===${NC}\"\n    echo -e \"Status: ${GREEN}$PROJECT_DIR/scripts/status.sh${NC}\"\n    echo -e \"Restart: ${GREEN}$PROJECT_DIR/scripts/restart.sh${NC}\"\n    echo -e \"Backup: ${GREEN}$PROJECT_DIR/scripts/backup.sh${NC}\"\n    echo -e \"Update: ${GREEN}$PROJECT_DIR/scripts/update.sh${NC}\"\n    echo \"\"\n    echo -e \"${BLUE}=== Next Steps ===${NC}\"\n    echo \"1. Wait 5-10 minutes for the indexer to populate initial data\"\n    echo \"2. Visit https://$DOMAIN to see the Kaspa Explorer\"\n    echo \"3. Check API health: https://$DOMAIN/health\"\n    echo \"4. Monitor services: https://$DOMAIN/monitoring/\"\n    echo \"5. Set up monitoring alerts in Grafana\"\n    echo \"\"\n    echo -e \"${GREEN}✅ Your Kaspa blockchain infrastructure is now running!${NC}\"\n}\n\n# Main deployment function\nmain() {\n    print_status \"Starting Kaspa Full-Stack Infrastructure Deployment\"\n    print_status \"Using official kaspa-ng repositories\"\n    print_status \"Target domain: $DOMAIN\"\n    echo \"\"\n    \n    check_system\n    install_dependencies\n    setup_firewall\n    setup_directories\n    clone_repositories\n    setup_ssl\n    setup_docker_config\n    setup_monitoring\n    start_services\n    setup_management_scripts\n    verify_deployment\n    \n    show_completion_info\n}\n\n# Error handling\ntrap 'print_error \"Deployment failed at line $LINENO. Exit code: $?\"' ERR\n\n# Run main function\nif [[ \"${BASH_SOURCE[0]}\" == \"${0}\" ]]; then\n    main \"$@\"\nfi